-- OTel logs, flattened (generated by scripts/nightly-perf/otel_corpus.py — do not edit).
-- Column order == the corpus parquet, so INSERT … SELECT * FROM s3(parquet) maps 1:1.
CREATE TABLE IF NOT EXISTS otel_logs
(
    time                               BIGINT NOT NULL,
    severity_text                      TEXT NOT NULL,
    severity_number                    BIGINT NOT NULL,
    service_name                       TEXT NOT NULL,
    body                               TEXT NOT NULL,
    trace_id                           TEXT NOT NULL,
    span_id                            TEXT NOT NULL,
    flags                              BIGINT NOT NULL,
    dropped_attributes_count           BIGINT NOT NULL,
    schema_url                         TEXT NOT NULL,
    instrumentation_scope_name         TEXT NOT NULL,
    instrumentation_scope_version      TEXT NOT NULL,
    log_http_method                    TEXT NOT NULL,
    log_http_url                       TEXT NOT NULL,
    log_http_status_code               BIGINT NOT NULL,
    log_http_request_id                TEXT NOT NULL,
    log_thread_id                      BIGINT NOT NULL,
    log_thread_name                    TEXT NOT NULL,
    log_code_filepath                  TEXT NOT NULL,
    log_code_function                  TEXT NOT NULL,
    log_code_lineno                    BIGINT NOT NULL,
    log_db_system                      TEXT NULL,
    log_db_statement                   TEXT NULL,
    log_exception_type                 TEXT NULL,
    log_exception_message              TEXT NULL,
    log_exception_stacktrace           TEXT NULL,
    resource_service_name              TEXT NOT NULL,
    resource_service_namespace         TEXT NOT NULL,
    resource_service_version           TEXT NOT NULL,
    resource_cloud_provider            TEXT NOT NULL,
    resource_cloud_region              TEXT NOT NULL,
    resource_cloud_availability_zone   TEXT NOT NULL,
    resource_cloud_account_id          TEXT NOT NULL,
    resource_k8s_namespace_name        TEXT NOT NULL,
    resource_k8s_pod_name              TEXT NOT NULL,
    resource_k8s_deployment_name       TEXT NOT NULL,
    resource_k8s_node_name             TEXT NOT NULL,
    resource_host_name                 TEXT NOT NULL,
    resource_host_id                   TEXT NOT NULL,
    resource_container_id              TEXT NOT NULL,
    resource_container_image_name      TEXT NOT NULL,
    resource_os_type                   TEXT NOT NULL,
    resource_deployment_environment    TEXT NOT NULL,
    resource_process_pid               BIGINT NOT NULL,
    resource_telemetry_sdk_language    TEXT NOT NULL,
    resource_telemetry_sdk_name        TEXT NOT NULL,
    resource_telemetry_sdk_version     TEXT NOT NULL
)
ENGINE = MergeTree
ORDER BY (service_name, time);
